using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "FervorousSundialOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/FervorousSundialOmenData")]
public class FervorousSundialOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.FervorousSundialOmenAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			ActivateOmen();
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.FervorousSundialOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), GetOmenConvertedDescriptionBattleAction().LowercaseFirst());
	}
}
